INSERT INTO news (slug, title, excerpt, category, status, published_at) VALUES ('news-1', 'تكريم الدكتور أحمد لحصوله على جائزة الملك فيصل العالمية', 'في حفل بهيج حضره كبار الشخصيات، تم تكريم ابن العائلة الدكتور أحمد نظير إسهاماته العلمية المتميزة في مجال الطب والجراحة، والتي رفعت اسم العائلة عالياً...', 'قصص نجاح', 'published', '2023-11-15') ON CONFLICT (slug) DO NOTHING;
--> statement-breakpoint
INSERT INTO news (slug, title, excerpt, category, status, published_at) VALUES ('news-2', 'تحديد موعد الاجتماع السنوي التاسع للعائلة في الرياض', 'يسر مجلس العائلة دعوة جميع الأفراد لحضور الاجتماع السنوي الذي سيقام في قاعة الاحتفالات الكبرى، وسيتضمن اللقاء فقرات متنوعة وتكريم للمتفوقين...', 'إعلانات', 'published', '2023-10-01') ON CONFLICT (slug) DO NOTHING;
--> statement-breakpoint
INSERT INTO news (slug, title, excerpt, category, status, published_at) VALUES ('news-3', 'افتتاح معرض الفنون التشكيلية لمواهب العائلة الشابة', 'في مبادرة لدعم المواهب، تم افتتاح المعرض الفني الذي يضم أكثر من ٥٠ عملاً فنياً من إبداع أبناء وبنات العائلة، ويستمر المعرض لمدة ثلاثة أيام...', 'فعاليات', 'published', '2023-09-20') ON CONFLICT (slug) DO NOTHING;
--> statement-breakpoint
INSERT INTO news (slug, title, excerpt, category, status, published_at) VALUES ('news-4', 'نعي فاضل: المغفور له بإذن الله الشيخ عبدالله', 'بقلوب مؤمنة بقضاء الله وقدره، تنعي العائلة فقيدها الشيخ عبدالله الذي وافته المنية صباح اليوم. وسيوارى جثمانه الثرى بعد صلاة العصر...', 'وفيات', 'published', '2023-08-10') ON CONFLICT (slug) DO NOTHING;
